<script lang="ts">
  import { onMount } from 'svelte';
  import SettingsHeader from '$lib/components/SettingsHeader.svelte';
  import { api } from '$lib/api';
  import type { Food, MealCategory, MealPlan, MealPlanItem, Recipe, RecipeIngredient } from '$lib/types';

  type Tab = 'plans' | 'recipes' | 'foods' | 'categories';
  type FoodDraft = { name: string; kcal: string; protein_g: string; carbs_g: string; fat_g: string; fiber_g: string };
  const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
  const emptyFood = (): FoodDraft => ({ name: '', kcal: '', protein_g: '', carbs_g: '', fat_g: '', fiber_g: '' });

  let tab: Tab = 'plans'; let loading = true; let saving = false; let error = ''; let notice = '';
  let categories: MealCategory[] = []; let foods: Food[] = []; let recipes: Recipe[] = []; let plans: MealPlan[] = [];
  let categoryName = ''; let foodDraft = emptyFood();
  let recipeName = ''; let recipeServings = '1'; let recipeNotes = ''; let recipeFoodId = ''; let recipeQuantity = '100'; let recipeDraft: RecipeIngredient[] = [];
  let editingRecipeId = ''; let editingRecipeDraft: RecipeIngredient[] = []; let editingRecipeFoodId = ''; let editingRecipeQuantity = '100'; let editingRecipeNotes = '';
  let planName = ''; let editingPlanId = ''; let planDraft: MealPlanItem[] = []; let selectedRecipeId = '';

  async function load() { loading = true; error = ''; try { [categories, foods, recipes, plans] = await Promise.all([api.getMealCategories(true), api.getFoods(), api.getRecipes(), api.getMealPlans()]); } catch { error = 'Die Mahlzeiten-Konfiguration konnte nicht geladen werden. Prüfe die Verbindung und versuche es erneut.'; } finally { loading = false; } }
  onMount(load);
  async function save(action: () => Promise<unknown>, success: string) { error = ''; notice = ''; saving = true; try { if (!await action()) throw new Error('empty'); notice = success; await load(); } catch { error = 'Änderung konnte nicht gespeichert werden. Deine Eingabe bleibt erhalten; versuche es erneut.'; } finally { saving = false; } }
  function foodName(id?: string | null) { return foods.find((food) => food.id === id)?.name ?? 'Unbekanntes Lebensmittel'; }
  function recipeNameFor(id?: string | null) { return recipes.find((recipe) => recipe.id === id)?.name ?? 'Unbekanntes Rezept'; }
  function nutrition(recipe: Recipe) { const n = recipe.nutrition; return n?.kcal == null ? 'Nährwerte unvollständig' : `${Math.round(Number(n.kcal))} kcal · ${Number(n.protein_g ?? 0).toFixed(1)} g Protein`; }
  function nutrient(value: string) { const number = Number(value); return value.trim() !== '' && Number.isFinite(number) && number >= 0 ? number : null; }

  function addCategory() { const name = categoryName.trim(); if (!name) { error = 'Bitte gib einen Namen für den Slot ein.'; return; } save(async () => { const value = await api.createMealCategory({ name, sort_order: categories.length, is_active: true }); if (value) categoryName = ''; return value; }, 'Slot gespeichert.'); }
  function moveCategory(index: number, direction: -1 | 1) { const next = [...categories]; const target = index + direction; if (target < 0 || target >= next.length) return; [next[index], next[target]] = [next[target], next[index]]; save(() => api.reorderMealCategories(next.map((category) => category.id)), 'Reihenfolge gespeichert.'); }
  function setCategoryActive(category: MealCategory) { save(() => api.updateMealCategory(category.id, { is_active: !category.is_active, updated_at: category.updated_at }), category.is_active ? 'Slot ausgeblendet.' : 'Slot eingeblendet.'); }
  function addFood() { const name = foodDraft.name.trim(); const kcal = nutrient(foodDraft.kcal); if (!name || kcal == null) { error = 'Name und kcal pro 100 g sind erforderlich.'; return; } save(async () => { const value = await api.createFood({ name, kcal, protein_g: nutrient(foodDraft.protein_g), carbs_g: nutrient(foodDraft.carbs_g), fat_g: nutrient(foodDraft.fat_g), fiber_g: nutrient(foodDraft.fiber_g) }); if (value) foodDraft = emptyFood(); return value; }, 'Lebensmittel gespeichert.'); }

  function addIngredient(editing = false) { const id = editing ? editingRecipeFoodId : recipeFoodId; const quantity = Number(editing ? editingRecipeQuantity : recipeQuantity); if (!id || !Number.isFinite(quantity) || quantity <= 0) { error = 'Wähle ein Lebensmittel und eine gültige Grammmenge.'; return; } const ingredient = { food_id: id, quantity, unit: 'g' as const, sort_order: (editing ? editingRecipeDraft : recipeDraft).length }; if (editing) { editingRecipeDraft = [...editingRecipeDraft, ingredient]; editingRecipeFoodId = ''; } else { recipeDraft = [...recipeDraft, ingredient]; recipeFoodId = ''; } }
  function removeIngredient(index: number, editing = false) { const items = (editing ? editingRecipeDraft : recipeDraft).filter((_, current) => current !== index).map((item, sort_order) => ({ ...item, sort_order })); if (editing) editingRecipeDraft = items; else recipeDraft = items; }
  function createRecipe() { const name = recipeName.trim(); const servings = Number(recipeServings); if (!name || !Number.isFinite(servings) || servings <= 0 || !recipeDraft.length) { error = 'Ein Gericht braucht einen Namen, mindestens eine Portion und eine Zutat.'; return; } save(async () => { const value = await api.createRecipe({ name, servings, notes: recipeNotes.trim() || null, status: 'active', ingredients: recipeDraft }); if (value) { recipeName = ''; recipeServings = '1'; recipeNotes = ''; recipeDraft = []; } return value; }, 'Rezept gespeichert; die Nährwerte wurden aus den Zutaten berechnet.'); }
  function startRecipeEdit(recipe: Recipe) { editingRecipeId = recipe.id; editingRecipeDraft = recipe.ingredients.map((item, sort_order) => ({ ...item, sort_order })); editingRecipeFoodId = ''; editingRecipeQuantity = '100'; editingRecipeNotes = recipe.notes ?? ''; }
  function saveRecipe(recipe: Recipe) { if (!editingRecipeDraft.length) { error = 'Ein Rezept muss mindestens eine Zutat enthalten.'; return; } save(() => api.updateRecipe(recipe.id, { notes: editingRecipeNotes.trim() || null, ingredients: editingRecipeDraft, expected_updated_at: recipe.updated_at }), 'Rezept und Nährwerte aktualisiert.'); editingRecipeId = ''; }
  function archiveRecipe(recipe: Recipe) { save(() => api.updateRecipe(recipe.id, { status: recipe.status === 'archived' ? 'active' : 'archived', updated_at: recipe.updated_at }), recipe.status === 'archived' ? 'Rezept reaktiviert.' : 'Rezept archiviert.'); }

  function addPlan() { const name = planName.trim(); if (!name) { error = 'Bitte gib einen Namen für den Plan ein.'; return; } save(async () => { const value = await api.createMealPlan({ name, is_active: plans.length === 0, items: [] }); if (value) planName = ''; return value; }, 'Wochenplan gespeichert.'); }
  function editPlan(plan: MealPlan) { editingPlanId = plan.id; selectedRecipeId = ''; planDraft = plan.items.map((item, sort_order) => ({ ...item, sort_order, weekdays: item.weekdays ? [...item.weekdays] : null })); }
  function itemFor(day: number, categoryId: string) { return planDraft.find((item) => item.category_id === categoryId && (item.weekdays?.includes(day) || item.weekdays == null)); }
  function placeRecipe(day: number, categoryId: string, recipeId: string) { if (!recipeId) return; const existing = itemFor(day, categoryId); const next: MealPlanItem = { category_id: categoryId, recipe_id: recipeId, name: null, weekdays: [day], portion: existing?.portion ?? 1, sort_order: planDraft.length }; planDraft = [...planDraft.filter((item) => item !== existing), next].map((item, sort_order) => ({ ...item, sort_order })); }
  function removePlanItem(day: number, categoryId: string) { const existing = itemFor(day, categoryId); if (!existing) return; planDraft = planDraft.filter((item) => item !== existing).map((item, sort_order) => ({ ...item, sort_order })); }
  function changePortion(day: number, categoryId: string, value: string) { const item = itemFor(day, categoryId); const portion = Number(value); if (!item || !Number.isFinite(portion) || portion <= 0) return; planDraft = planDraft.map((current) => current === item ? { ...current, portion } : current); }
  function savePlan(plan: MealPlan) { save(() => api.updateMealPlan(plan.id, { items: planDraft.map(({ id: _id, ...item }) => item), expected_updated_at: plan.updated_at }), 'Wochenplan gespeichert.'); editingPlanId = ''; }
  function activatePlan(plan: MealPlan) { save(() => api.updateMealPlan(plan.id, { is_active: true, updated_at: plan.updated_at }), 'Plan aktiviert.'); }
</script>

<svelte:head><title>FitTrack – Mahlzeiten konfigurieren</title></svelte:head>
<div class="page">
  <SettingsHeader title="Mahlzeiten" subtitle="Lebensmittel, Rezepte und Wochenplanung" />
  <p class="intro">Lebensmittel liefern die Basiswerte. Jedes Gericht ist ein Rezept mit Zutaten; seine Nährwerte werden automatisch aus den Mengen berechnet.</p>
  <div class="tabs" role="tablist" aria-label="Mahlzeiten konfigurieren"><button role="tab" class:active={tab === 'plans'} aria-selected={tab === 'plans'} onclick={() => tab = 'plans'}>Wochenplan</button><button role="tab" class:active={tab === 'recipes'} aria-selected={tab === 'recipes'} onclick={() => tab = 'recipes'}>Rezepte</button><button role="tab" class:active={tab === 'foods'} aria-selected={tab === 'foods'} onclick={() => tab = 'foods'}>Lebensmittel</button><button role="tab" class:active={tab === 'categories'} aria-selected={tab === 'categories'} onclick={() => tab = 'categories'}>Mahlzeiten-Slots</button></div>
  {#if error}<div class="message error" role="alert">{error}</div>{/if}{#if notice}<div class="message success" role="status">{notice}</div>{/if}
  {#if loading}<div class="loading" role="status">Lade Mahlzeiten-Konfiguration…</div>
  {:else if tab === 'foods'}
    <section class="section-card"><div class="section-header"><h2>Lebensmittel</h2><span>{foods.length} gespeichert</span></div><p class="section-copy">Alle Werte gelten pro 100 g. Unbekannte Werte bleiben leer, statt als 0 gerechnet zu werden.</p><form class="food-form" onsubmit={(event) => { event.preventDefault(); addFood(); }}><input aria-label="Name" placeholder="z. B. Haferflocken" bind:value={foodDraft.name} maxlength="120" /><input aria-label="kcal pro 100 Gramm" type="number" min="0" step="0.1" placeholder="kcal" bind:value={foodDraft.kcal} /><input aria-label="Protein pro 100 Gramm" type="number" min="0" step="0.1" placeholder="Protein g" bind:value={foodDraft.protein_g} /><input aria-label="Kohlenhydrate pro 100 Gramm" type="number" min="0" step="0.1" placeholder="KH g" bind:value={foodDraft.carbs_g} /><input aria-label="Fett pro 100 Gramm" type="number" min="0" step="0.1" placeholder="Fett g" bind:value={foodDraft.fat_g} /><input aria-label="Ballaststoffe pro 100 Gramm" type="number" min="0" step="0.1" placeholder="Ballaststoffe g" bind:value={foodDraft.fiber_g} /><button class="primary" disabled={saving}>Lebensmittel anlegen</button></form><div class="list">{#each foods as food (food.id)}<div class="row"><div class="row-main"><strong>{food.name}</strong><small>{food.kcal ?? '–'} kcal · P {food.protein_g ?? '–'} g · KH {food.carbs_g ?? '–'} g · F {food.fat_g ?? '–'} g / 100 g</small></div></div>{:else}<div class="empty">Lege zuerst Lebensmittel an. Danach kannst du sie in Rezepten abwiegen.</div>{/each}</div></section>
  {:else if tab === 'recipes'}
    <section class="section-card"><div class="section-header"><h2>Neues Rezept</h2><span>Gerichte sind immer Rezepte</span></div><p class="section-copy">Füge die tatsächlich verwendeten Lebensmittel und Mengen hinzu. Die Berechnung erfolgt auf dem Server pro Portion.</p><form class="recipe-editor" onsubmit={(event) => { event.preventDefault(); createRecipe(); }}><div class="form-row"><input aria-label="Rezeptname" placeholder="z. B. Protein-Porridge" bind:value={recipeName} maxlength="120" /><input aria-label="Anzahl Portionen" type="number" min="0.001" step="0.001" bind:value={recipeServings} /></div><textarea aria-label="Notizen oder Zubereitung" placeholder="Zubereitung / Notizen (optional)" bind:value={recipeNotes}></textarea><div class="ingredient-add"><select aria-label="Lebensmittel" bind:value={recipeFoodId}><option value="">Lebensmittel auswählen…</option>{#each foods as food}<option value={food.id}>{food.name}</option>{/each}</select><input aria-label="Menge in Gramm" type="number" min="0.001" step="0.001" bind:value={recipeQuantity} /><button type="button" onclick={() => addIngredient()}>Zutat hinzufügen</button></div><div class="ingredient-list">{#each recipeDraft as ingredient, index}<div><span>{foodName(ingredient.food_id)} · {ingredient.quantity} g</span><button type="button" onclick={() => removeIngredient(index)}>×</button></div>{:else}<small>Mindestens eine Zutat erforderlich.</small>{/each}</div><button class="primary" disabled={saving}>Rezept speichern</button></form></section>
    <section class="section-card"><div class="section-header"><h2>Rezeptbibliothek</h2><span>{recipes.filter((recipe) => recipe.status !== 'archived').length} aktiv</span></div><div class="list">{#each recipes as recipe (recipe.id)}<article class:archived={recipe.status === 'archived'} class="recipe-row">{#if editingRecipeId === recipe.id}<form class="recipe-editor" onsubmit={(event) => { event.preventDefault(); saveRecipe(recipe); }}><strong>{recipe.name} · {recipe.servings} Portion{Number(recipe.servings) === 1 ? '' : 'en'}</strong><textarea aria-label="Notizen oder Zubereitung" bind:value={editingRecipeNotes}></textarea><div class="ingredient-add"><select aria-label="Lebensmittel" bind:value={editingRecipeFoodId}><option value="">Lebensmittel auswählen…</option>{#each foods as food}<option value={food.id}>{food.name}</option>{/each}</select><input aria-label="Menge in Gramm" type="number" min="0.001" step="0.001" bind:value={editingRecipeQuantity} /><button type="button" onclick={() => addIngredient(true)}>Hinzufügen</button></div><div class="ingredient-list">{#each editingRecipeDraft as ingredient, index}<div><span>{foodName(ingredient.food_id)} · {ingredient.quantity} g</span><button type="button" onclick={() => removeIngredient(index, true)}>×</button></div>{/each}</div><div class="row-actions"><button class="primary" disabled={saving}>Speichern</button><button type="button" onclick={() => editingRecipeId = ''}>Abbrechen</button></div></form>{:else}<div class="row-main"><strong>{recipe.name}</strong><small>{recipe.ingredients.map((ingredient) => `${foodName(ingredient.food_id)} (${ingredient.quantity} g)`).join(' · ')}</small><small>{nutrition(recipe)} pro Portion{#if recipe.notes} · {recipe.notes}{/if}</small></div><div class="row-actions"><button onclick={() => startRecipeEdit(recipe)}>Bearbeiten</button><button onclick={() => archiveRecipe(recipe)}>{recipe.status === 'archived' ? 'Reaktivieren' : 'Archivieren'}</button></div>{/if}</article>{:else}<div class="empty">Noch kein Rezept. Lege Lebensmittel an und erstelle daraus dein erstes Gericht.</div>{/each}</div></section>
  {:else if tab === 'plans'}
    <section class="section-card">
      <div class="section-header"><h2>Wochenplan</h2><span>{plans.length} gespeichert</span></div>
      <p class="section-copy">Wähle für jeden Tages-Slot ein Rezept und passe bei Bedarf die Portion an.</p>
      <form class="form-row" onsubmit={(event) => { event.preventDefault(); addPlan(); }}><input aria-label="Name des Wochenplans" placeholder="z. B. Arbeitstage" bind:value={planName} maxlength="120" /><button class="primary" disabled={saving}>Plan anlegen</button></form>
      <div class="list">
        {#each plans as plan (plan.id)}
          {#if editingPlanId === plan.id}
            <div class="planner">
              <div class="planner-toolbar">
                <label>Rezept für leere Slots
                  <select bind:value={selectedRecipeId} aria-label="Rezept für leere Slots auswählen">
                    <option value="">Rezept auswählen…</option>
                    {#each recipes.filter((recipe) => recipe.status === 'active') as recipe (recipe.id)}<option value={recipe.id}>{recipe.name}</option>{/each}
                  </select>
                </label>
                <small>Danach einen freien Slot wählen. Bereits belegte Slots lassen sich direkt ändern.</small>
              </div>
              <div class="week-grid" aria-label="Wochenplan nach Tagen und Mahlzeiten">
                {#each DAYS as day, dayIndex}
                  <section class="day-card"><h3>{day}</h3>
                    {#each categories.filter((category) => category.is_active) as category}
                      {@const item = itemFor(dayIndex, category.id)}
                      <div class="meal-slot" class:filled={Boolean(item)}>
                        <small>{category.name}</small>
                        {#if item}
                          <strong>{recipeNameFor(item.recipe_id)}</strong>
                          <label>Rezept
                            <select aria-label={`${category.name} am ${day} ändern`} value={item.recipe_id ?? ''} onchange={(event) => placeRecipe(dayIndex, category.id, (event.currentTarget as HTMLSelectElement).value)}>
                              <option value="">Rezept auswählen…</option>
                              {#each recipes.filter((recipe) => recipe.status === 'active') as recipe (recipe.id)}<option value={recipe.id}>{recipe.name}</option>{/each}
                            </select>
                          </label>
                          <label>Portionen <input type="number" min="0.001" step="0.001" value={item.portion ?? 1} onchange={(event) => changePortion(dayIndex, category.id, (event.currentTarget as HTMLInputElement).value)} /></label>
                          <button class="remove-slot" onclick={() => removePlanItem(dayIndex, category.id)}>Entfernen</button>
                        {:else}
                          <button class="assign-slot" disabled={!selectedRecipeId} onclick={() => placeRecipe(dayIndex, category.id, selectedRecipeId)}>Rezept zuweisen</button>
                        {/if}
                      </div>
                    {/each}
                  </section>
                {/each}
              </div>
              <div class="row-actions"><button class="primary" onclick={() => savePlan(plan)} disabled={saving}>Plan speichern</button><button onclick={() => editingPlanId = ''}>Abbrechen</button></div>
            </div>
          {:else}
            <div class="row"><div class="row-main"><strong>{plan.name}</strong><small>{plan.items.length} belegte Slots {#if plan.is_active}· aktiv{/if}</small></div><div class="row-actions"><button onclick={() => editPlan(plan)}>Wochenplan bearbeiten</button>{#if !plan.is_active}<button onclick={() => activatePlan(plan)}>Aktivieren</button>{/if}</div></div>
          {/if}
        {:else}<div class="empty">Noch kein Wochenplan. Lege einen Plan an und verteile deine Rezepte auf die Tage.</div>
        {/each}
      </div>
    </section>
  {:else}
    <section class="section-card"><div class="section-header"><h2>Mahlzeiten-Slots</h2><span>{categories.filter((category) => category.is_active).length} aktiv</span></div><p class="section-copy">Slots sind die Zeilen deines Tages, etwa Frühstück, Mittagessen oder Snack. Sie erscheinen in jedem Tag des Wochenplans.</p><form class="form-row" onsubmit={(event) => { event.preventDefault(); addCategory(); }}><input aria-label="Name des neuen Slots" placeholder="z. B. Frühstück" bind:value={categoryName} maxlength="80" /><button class="primary" disabled={saving}>Slot hinzufügen</button></form><div class="list">{#each categories as category, index (category.id)}<div class:archived={!category.is_active} class="row"><div class="row-main"><strong>{category.name}</strong><small>{category.is_active ? 'im Plan sichtbar' : 'ausgeblendet'}</small></div><div class="row-actions"><button disabled={index === 0 || saving} onclick={() => moveCategory(index, -1)}>↑</button><button disabled={index === categories.length - 1 || saving} onclick={() => moveCategory(index, 1)}>↓</button><button onclick={() => setCategoryActive(category)}>{category.is_active ? 'Ausblenden' : 'Einblenden'}</button></div></div>{:else}<div class="empty">Lege mindestens einen Slot an, bevor du planst.</div>{/each}</div></section>
  {/if}
</div>

<style>
  .page { display:grid; gap:12px; min-width:0; padding-bottom:24px; } .intro,.section-copy { margin:0; color:var(--text-dim); font-size:13px; line-height:1.45; } .tabs { display:flex; overflow-x:auto; gap:6px; } button,input,select,textarea { font:inherit; } button { cursor:pointer; } .tabs button,.row-actions button,.ingredient-add button,.remove-slot,.assign-slot { min-height:36px; border:1px solid var(--border-2); border-radius:8px; background:var(--card); color:var(--text-dim); padding:6px 10px; white-space:nowrap; } .tabs button.active { background:var(--green); border-color:var(--green); color:#07120a; font-weight:700; } button:disabled { opacity:.5; cursor:not-allowed; } button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible { outline:2px solid var(--blue); outline-offset:2px; } .section-card { overflow:hidden; border:1px solid var(--border); border-radius:12px; background:var(--card); } .section-header { display:flex; align-items:baseline; justify-content:space-between; gap:12px; padding:14px 14px 8px; } h2,h3,p { margin:0; } h2 { font-size:15px; } h3 { font-size:13px; } .section-header span,small { color:var(--text-faint); font-size:12px; } .section-copy { padding:0 14px 12px; } .form-row,.food-form,.recipe-editor,.ingredient-add { display:flex; gap:8px; padding:0 14px 14px; } input,select,textarea { min-width:0; min-height:40px; box-sizing:border-box; border:1px solid var(--border-2); border-radius:8px; background:var(--card-2); color:var(--text); padding:0 10px; } textarea { width:100%; min-height:75px; padding:10px; resize:vertical; } .form-row input { flex:1; } .food-form { display:grid; grid-template-columns:minmax(160px,2fr) repeat(5,minmax(92px,1fr)) auto; } .primary { min-height:40px; border:0; border-radius:8px; background:var(--green); color:#07120a; padding:0 12px; font-weight:700; } .list { border-top:1px solid var(--border); } .row,.recipe-row { display:flex; align-items:center; gap:10px; padding:11px 14px; border-bottom:1px solid var(--border); } .recipe-row { align-items:flex-start; } .row-main { display:grid; min-width:0; flex:1; gap:3px; } strong { font-size:14px; } .row-main small { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } .row-actions { display:flex; align-items:center; flex-wrap:wrap; gap:4px; } .empty,.loading,.message { padding:14px; font-size:13px; line-height:1.4; } .empty,.loading { color:var(--text-faint); } .message { border-radius:8px; } .error { color:var(--red); background:color-mix(in srgb,var(--red) 12%,transparent); } .success { color:var(--green); background:color-mix(in srgb,var(--green) 12%,transparent); } .recipe-editor { display:grid; } .recipe-editor .form-row,.recipe-editor .ingredient-add { padding:0; } .ingredient-add select { flex:1; } .ingredient-add input { width:110px; } .ingredient-list { display:grid; gap:5px; padding:8px; border-radius:8px; background:var(--card-2); } .ingredient-list div { display:flex; align-items:center; justify-content:space-between; gap:8px; font-size:13px; } .ingredient-list button { border:0; background:transparent; color:var(--red); font-size:18px; } .archived { opacity:.55; } .planner { display:grid; gap:16px; padding:14px; } .planner-toolbar { display:flex; align-items:end; gap:12px; padding:12px; border:1px solid var(--border); border-radius:10px; background:var(--card-2); } .planner-toolbar label { display:grid; flex:0 1 300px; gap:5px; color:var(--text-dim); font-size:12px; } .planner-toolbar small { max-width:360px; line-height:1.4; } .week-grid { display:grid; grid-template-columns:repeat(7,minmax(145px,1fr)); gap:8px; overflow-x:auto; padding:2px 2px 10px; scrollbar-width:thin; } .week-grid::-webkit-scrollbar { width:8px; height:8px; } .week-grid::-webkit-scrollbar-thumb { border-radius:999px; background:var(--border-2); } .day-card { display:grid; align-content:start; gap:7px; min-width:145px; } .day-card h3 { padding:2px 2px 5px; } .meal-slot { display:grid; min-height:116px; align-co